mapper.select:
SELECT m.*, ml.level_name, ml.discount_rate
FROM member m
JOIN member_level ml ON ml.level_id = m.level_id


        AND m.role = #{role}


        AND (m.username LIKE CONCAT('%', #{kw}, '%')
             OR m.nickname LIKE CONCAT('%', #{kw}, '%')
             OR m.phone LIKE CONCAT('%', #{kw}, '%'))


        AND m.level_id = #{levelId}


        AND m.status = #{status}


ORDER BY m.member_id ASC
